    let private smallPowers = [| 1UL; 5UL; 25UL; 125UL; 625UL; 3125UL; 15625UL; 78125UL; 390625UL; 1953125UL; 9765625UL; 48828125UL; 244140625UL; 1220703125UL; 6103515625UL; 30517578125UL; 152587890625UL; 762939453125UL; 3814697265625UL; 19073486328125UL; 95367431640625UL; 476837158203125UL; 2384185791015625UL; 11920928955078125UL; 59604644775390625UL; 298023223876953125UL; 1490116119384765625UL; 7450580596923828125UL |]

    let inline binaryFloor (value: uint64) =
        let mutable word = value
        let mutable bit = 0
        if word >>> 32 <> 0UL then word <- word >>> 32; bit <- bit + 32
        if word >>> 16 <> 0UL then word <- word >>> 16; bit <- bit + 16
        if word >>> 8 <> 0UL then word <- word >>> 8; bit <- bit + 8
        if word >>> 4 <> 0UL then word <- word >>> 4; bit <- bit + 4
        if word >>> 2 <> 0UL then word <- word >>> 2; bit <- bit + 2
        if word >>> 1 <> 0UL then bit <- bit + 1
        bit

    let private product left right =
        let a = left &&& 0xffffffffUL
        let b = left >>> 32
        let c = right &&& 0xffffffffUL
        let d = right >>> 32
        let ac = a * c
        let bc = b * c + (ac >>> 32)
        let ad = a * d + (bc &&& 0xffffffffUL)
        struct((ad <<< 32) ||| (ac &&& 0xffffffffUL), b * d + (bc >>> 32) + (ad >>> 32))

    let private shifted low middle high bits =
        if bits >= 192 then 0UL
        elif bits >= 128 then high >>> (bits - 128)
        elif bits = 64 then middle
        elif bits > 64 then (high <<< (128 - bits)) ||| (middle >>> (bits - 64))
        elif bits = 0 then low
        else (middle <<< (64 - bits)) ||| (low >>> bits)

    let private belowZero low middle high bits =
        let mask count = if count = 64 then System.UInt64.MaxValue else (1UL <<< count) - 1UL
        if bits >= 192 then low = 0UL && middle = 0UL && high = 0UL
        elif bits > 128 then low = 0UL && middle = 0UL && high &&& mask(bits - 128) = 0UL
        elif bits = 128 then low = 0UL && middle = 0UL
        elif bits > 64 then low = 0UL && middle &&& mask(bits - 64) = 0UL
        elif bits = 64 then low = 0UL
        else low &&& mask bits = 0UL

    let private half low middle high bits =
        let index = bits - 1
        if index >= 192 then 0UL
        elif index >= 128 then (high >>> (index - 128)) &&& 1UL
        elif index >= 64 then (middle >>> (index - 64)) &&& 1UL
        else (low >>> index) &&& 1UL

    /// Fraction: zero, below half, exactly half or above half. An uncertified
    /// enclosure belongs to the same owner's exact quotient/remainder path.
    let integer coefficient binaryExponent decimalExponent =
        let struct(factorLow,factorHigh,exponent,exact) = factors[decimalExponent + 340]
        let struct(low,carry) = product coefficient factorLow
        let struct(part,high) = product coefficient factorHigh
        let middle = carry + part
        let high = high + (if middle < carry then 1UL else 0UL)
        let bits = 127 - exponent - binaryExponent + decimalExponent
        let fits =
            bits >= 128 || (bits >= 64 && (if bits = 64 then high = 0UL else high >>> (bits - 64) = 0UL))
            || (bits >= 0 && bits < 64 && high = 0UL && (if bits = 0 then middle = 0UL else middle >>> bits = 0UL))
        if bits <= 0 || not fits then { Valid = false; Floor = 0UL; Fraction = 0 } else
        let floor = shifted low middle high bits
        let midpoint = half low middle high bits
        if exact then
            let fraction =
                if belowZero low middle high bits then 0
                elif midpoint = 0UL then 1
                elif belowZero low middle high (bits - 1) then 2 else 3
            { Valid = true; Floor = floor; Fraction = fraction }
        else
            let upperLow = low + coefficient
            let upperMiddle = middle + (if upperLow < low then 1UL else 0UL)
            let upperHigh = high + (if upperMiddle < middle then 1UL else 0UL)
            if shifted upperLow upperMiddle upperHigh bits = floor && half upperLow upperMiddle upperHigh bits = midpoint then
                { Valid = true; Floor = floor; Fraction = if midpoint = 0UL then 1 else 3 }
            else { Valid = false; Floor = 0UL; Fraction = 0 }

    /// An exact decimal is shortest when its quantum exceeds the target's half-ulp.
    let exactCoefficient mantissa binaryExponent =
        let mutable value = mantissa
        let mutable exponent = binaryExponent
        let mutable valid = true
        if exponent >= 0 then
            if exponent > 63 || value > (System.UInt64.MaxValue >>> exponent) then valid <- false
            else value <- value <<< exponent; exponent <- 0
        else
            let mutable word = value
            let mutable zeros = 0
            if word &&& 0xffffffffUL = 0UL then word <- word >>> 32; zeros <- zeros + 32
            if word &&& 0xffffUL = 0UL then word <- word >>> 16; zeros <- zeros + 16
            if word &&& 0xffUL = 0UL then word <- word >>> 8; zeros <- zeros + 8
            if word &&& 15UL = 0UL then word <- word >>> 4; zeros <- zeros + 4
            if word &&& 3UL = 0UL then word <- word >>> 2; zeros <- zeros + 2
            if word &&& 1UL = 0UL then zeros <- zeros + 1
            let remove = min zeros (-exponent)
            value <- value >>> remove
            exponent <- exponent + remove
            if -exponent >= smallPowers.Length then valid <- false
            else
                let power = smallPowers[-exponent]
                if value > System.UInt64.MaxValue / power then valid <- false
                else value <- value * power
        if valid then
            while value % 10UL = 0UL do value <- value / 10UL; exponent <- exponent + 1
            valid <- value < 2UL * mantissa
        struct(valid,value,exponent)
